package com.vms.vendorcontractmanagement.repository; import com.vms.vendorcontractmanagement.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.domain.*; public interface VendorRepository extends JpaRepository<Vendor,Long>{ boolean existsByVendorCode(String vendorCode); @Query("select v from Vendor v where (:search is null or lower(v.vendorName) like lower(concat('%',:search,'%')) or lower(v.vendorCode) like lower(concat('%',:search,'%'))) and (:category is null or v.category=:category) and (:status is null or v.status=:status)") Page<Vendor> search(String search,String category,String status,Pageable pageable); }
